-- All fixtures and simulated publication state are rolled back. No external sends.
begin;
DO $tests$
declare sid uuid; a uuid; b uuid; c uuid; d uuid; e uuid; f uuid; g uuid; h uuid; pub uuid;
 actor uuid:=gen_random_uuid(); ts timestamptz; got jsonb; blocked boolean; text_value text;
begin
 if news_url_key('https://www.example.test/news/42/?utm_source=tg&item=7#photo')<>news_url_key('https://example.test/news/42?item=7') then raise exception 'Tracking URL normalization failed'; end if;
 if news_url_key('https://example.test/news?item=7')=news_url_key('https://example.test/news?item=8') then raise exception 'Functional query was removed'; end if;
 insert into sources(name,url,tier,source_type) values('Regression fixture','https://dedup-test.invalid/','B','local_media') returning id into sid;
 text_value:=repeat('QA exact body regression event alpha has unique content not found in real reports. ',10);
 insert into articles(source_id,title,url,body,published_at) values(sid,'QA exact alpha event first source','https://dedup-test.invalid/a',text_value,'2050-01-01') returning id into a;
 insert into articles(source_id,title,url,body,published_at) values(sid,'QA exact alpha event second source','https://dedup-test.invalid/b',text_value,'2050-01-01') returning id into b;
 if not exists(select 1 from article_duplicate_links where article_id=least(a,b) and other_id=greatest(a,b) and kind='exact_text') then raise exception 'Exact content not detected'; end if;
 select updated_at into ts from articles where id=b;
 blocked:=false; begin perform editorial_console_resolve_duplicate(b,'distinct',actor,'rusboma@gmail.com',ts,'These are new facts rather than the original report.'); exception when others then if sqlerrm like 'EXACT_DUPLICATE%' then blocked:=true; else raise; end if; end;
 if not blocked then raise exception 'Exact text override was allowed'; end if;
 select updated_at into ts from articles where id=a;
 perform editorial_console_resolve_duplicate(a,'primary',actor,'rusboma@gmail.com',ts,'Use the first source as the primary report of this event.');
 update articles set status='approved' where id=a;
 blocked:=false; begin update articles set status='approved' where id=b; exception when others then if sqlerrm like 'DUPLICATE_BLOCKED%' then blocked:=true; else raise; end if; end;
 if not blocked then raise exception 'Second approval was allowed'; end if;
 got:=news_reserve_publication(a,'QA reservation','No external publication');
 pub:=(got->>'id')::uuid;
 blocked:=false; begin perform news_reserve_publication(a,'QA repeated publication','No external publication'); exception when others then if sqlerrm like 'DUPLICATE_BLOCKED%' then blocked:=true; else raise; end if; end;
 if not blocked then raise exception 'Repeat reservation was allowed'; end if;
 update publications set status='published',published_at=now() where id=pub;
 update articles set status='published' where id=a;
 blocked:=false; begin insert into publications(article_id,title,body,status) values(b,'QA copy of published event','No external publication','published'); exception when others then if sqlerrm like 'DUPLICATE_BLOCKED%' then blocked:=true; else raise; end if; end;
 if not blocked then raise exception 'Published event copy was allowed'; end if;
 got:=scout_ingest_item(jsonb_build_object('source_url','https://dedup-test.invalid/','url','https://dedup-test.invalid/a?utm_campaign=repeat','title','QA repeated URL','body',text_value));
 if got->>'status'<>'duplicate' or (got->>'id')::uuid<>a then raise exception 'Tracking URL ingest not deduplicated'; end if;
 insert into articles(source_id,title,url,body,published_at) values(sid,'QA significant beta event with meaningful revised facts','https://dedup-test.invalid/c',repeat('Original beta event water delivery includes original measurements. ',10),'2050-02-01') returning id into c;
 insert into articles(source_id,title,url,body,published_at) values(sid,'QA significant beta event with meaningful revised facts','https://dedup-test.invalid/d',repeat('New beta event water delivery has an updated court ruling and new measurements. ',10),'2050-02-02') returning id into d;
 if not exists(select 1 from article_duplicate_links where article_id=least(c,d) and other_id=greatest(c,d) and kind='possible_event') then raise exception 'Same-event candidate not detected'; end if;
 blocked:=false; begin update articles set status='approved' where id=d; exception when others then if sqlerrm like 'DUPLICATE_REVIEW_REQUIRED%' then blocked:=true; else raise; end if; end;
 if not blocked then raise exception 'Unreviewed event was allowed'; end if;
 select updated_at into ts from articles where id=c;
 perform editorial_console_resolve_duplicate(c,'primary',actor,'rusboma@gmail.com',ts,'The original beta report is the primary material for this event.');
 update articles set status='approved' where id=c;
 select updated_at into ts from articles where id=d;
 got:=editorial_console_resolve_duplicate(d,'distinct',actor,'rusboma@gmail.com',ts,'A new court ruling changes the outcome; this is a significant development.');
 if not got ? 'updated_at' or jsonb_array_length(got->'duplicates')<>0 then raise exception 'Resolution response is stale'; end if;
 update articles set status='approved' where id=d;
 if not exists(select 1 from editorial_actions where article_id=d and action='dedup_distinct' and note like '%new court ruling%') then raise exception 'Update justification was not audited'; end if;
 insert into articles(source_id,title,url,body,published_at) values(sid,'QA significant beta event with meaningful revised facts','https://dedup-test.invalid/e',repeat('A separate housing event with different dated facts and another municipality. ',10),'2050-03-15') returning id into e;
 if (select count(*) from news_component(e))<>1 then raise exception 'A later different event was suppressed'; end if;
 insert into articles(source_id,title,url,published_at) values(sid,'QA chain first unrelated fixture','https://dedup-test.invalid/f','2060-01-01') returning id into f;
 insert into articles(source_id,title,url,published_at) values(sid,'QA chain middle unrelated fixture','https://dedup-test.invalid/g','2061-01-01') returning id into g;
 insert into articles(source_id,title,url,published_at) values(sid,'QA chain last unrelated fixture','https://dedup-test.invalid/h','2062-01-01') returning id into h;
 insert into article_duplicate_links(article_id,other_id,kind,score) values(least(f,g),greatest(f,g),'possible_event',0.8),(least(g,h),greatest(g,h),'possible_event',0.8);
 select updated_at into ts from articles where id=f;
 perform editorial_console_resolve_duplicate(f,'primary',actor,'rusboma@gmail.com',ts,'Choose the first report as the primary of the linked event.');
 update articles set status='approved' where id=f;
 blocked:=false; begin update articles set status='approved' where id=h; exception when others then if sqlerrm like 'DUPLICATE_BLOCKED%' then blocked:=true; else raise; end if; end;
 if not blocked or jsonb_array_length(editorial_console_duplicates(h))<>2 then raise exception 'Transitive event guard failed'; end if;
 blocked:=false; begin insert into publications(title,body,status) values('QA missing article','No external sends','approved'); exception when others then if sqlerrm like 'DUPLICATE_REVIEW_REQUIRED%' then blocked:=true; else raise; end if; end;
 if not blocked then raise exception 'Unlinked publication bypass was allowed'; end if;
 if has_function_privilege('anon','public.editorial_console_resolve_duplicate(uuid,text,uuid,text,timestamptz,text)','execute') or has_table_privilege('authenticated','public.article_duplicate_links','select') then raise exception 'Private duplicate access is exposed'; end if;
end $tests$;
rollback;
